import * as React from "react"

import { cn } from "cn"

/**
 * Any link component that renders an anchor from `href` + anchor props:
 * a plain `"a"` (the default), Next.js `Link`, React Router's `Link`, or a
 * locale-aware wrapper from your i18n library.
 */
export type SiteLinkComponent = React.ElementType<
  React.AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }
>

export interface MonarkMarkProps extends React.SVGProps<SVGSVGElement> {
  /**
   * Accessible name. Omit it (the default) when the mark sits next to text
   * that already names the product: the mark is then decorative.
   */
  title?: string
}

