/**
 * The official horizontal Monark logo (butterfly + wordmark) as one inline
 * SVG. The butterfly keeps its brand gradient; the wordmark is drawn in
 * `currentColor`, so it follows `text-foreground` and serves both the
 * on-light (#141414) and on-dark (white) brand-kit variants. Size it by
 * height (`h-9` by default); the width follows the aspect ratio.
 */
function MonarkLogo({ title = "Monark", className, ...props }: MonarkLogoProps) {
  const id = `monark-logo-${React.useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  return (
    <svg
      viewBox="14 47 676 130"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      data-slot="monark-logo"
      role="img"
      aria-label={title}
      focusable="false"
      className={cn("h-9 w-auto shrink-0 text-foreground", className)}
      {...props}
    >
      <title>{title}</title>
      {MONARK_LOGO_MARK.map((d, index) => (
        <path key={index} d={d} fill={`url(#${id}-${index})`} />
      ))}
      <path d={MONARK_WORDMARK} fill="currentColor" />
      <defs>
        {MONARK_LOGO_GRADIENTS.map(([x1, y1, x2, y2], index) => (
          <linearGradient
            key={index}
            id={`${id}-${index}`}
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            gradientUnits="userSpaceOnUse"
          >
            <stop stopColor="#ED2723" />
            <stop offset="1" stopColor="#FBA60B" />
          </linearGradient>
        ))}
      </defs>
    </svg>
  )
}

export interface SiteBrandProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "href"> {
  /** The product name, e.g. "Splitflow". Set in text, never as an image. */
  name: React.ReactNode
  /** The site's home page. Default `/`; pass the locale root (`/fr`) on localised sites. */
  href?: string
  /**
   * The link's accessible name. Defaults to `"{name}, by Monark: home"`
   * when `name` is a string; pass a translated label on non-English pages.
   */
  "aria-label"?: string
  /** Link component used for the home link. Default: a plain `<a>`. */
  LinkComponent?: SiteLinkComponent
}

/**
 * The Monark product brand for a site header: the colour butterfly mark
 * (28px), a 10px gap, then the product name in Nunito Sans 800 at 18px.
 * No "by Monark" here; that credit belongs in the footer.
 */
function SiteBrand({
  name,
  href = "/",
  "aria-label": ariaLabel,
  LinkComponent = "a",
  className,
  ...props
}: SiteBrandProps) {
  const label =
    ariaLabel ?? (typeof name === "string" ? `${name}, by Monark: home` : undefined)
  return (
    <LinkComponent
      href={href}
      aria-label={label}
      data-slot="site-brand"
      className={cn(
        "inline-flex shrink-0 items-center gap-2.5 rounded-md py-1 pr-1 whitespace-nowrap outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
        className
      )}
      {...props}
    >
      <MonarkMark className="size-7" />
      <span className="text-lg leading-none font-extrabold tracking-[-0.02em] text-foreground">
        {name}
      </span>
    </LinkComponent>
  )
}

export { SiteBrand, MonarkMark, MonarkLogo }
